LEGACY_RECORDS = [{'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/demand.csv', 'values': {'Customer': 'Customer_1', 'demand': '2397'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/demand.csv', 'values': {'Customer': 'Customer_2', 'demand': '1889'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/demand.csv', 'values': {'Customer': 'Customer_3', 'demand': '2518'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/demand.csv', 'values': {'Customer': 'Customer_4', 'demand': '3218'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/demand.csv', 'values': {'Customer': 'Customer_5', 'demand': '1813'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/fixed_cost.csv', 'values': {'Unnamed: 0': 'MOUNT AYR', 'fixed_costs': '96.58'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/fixed_cost.csv', 'values': {'Unnamed: 0': 'WAUKEE', 'fixed_costs': '94.06'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/fixed_cost.csv', 'values': {'Unnamed: 0': 'WAVERLY', 'fixed_costs': '94.37'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/fixed_cost.csv', 'values': {'Unnamed: 0': 'PELLA', 'fixed_costs': '82.88'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/fixed_cost.csv', 'values': {'Unnamed: 0': 'DES MOINES', 'fixed_costs': '94.95999999999999'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/transportation_costs.csv', 'values': {'Unnamed: 0': 'MOUNT AYR', 'CLARINDA': '694.6799999999999', 'FORT MADISON': '17.48', 'SIOUX CITY': '20.07', 'TOLEDO': '199.02', 'BANCROFT': '1685.53'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/transportation_costs.csv', 'values': {'Unnamed: 0': 'WAUKEE', 'CLARINDA': '15.13', 'FORT MADISON': '1.5', 'SIOUX CITY': '1.43', 'TOLEDO': '27.88', 'BANCROFT': '90.69'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/transportation_costs.csv', 'values': {'Unnamed: 0': 'WAVERLY', 'CLARINDA': '2.34', 'FORT MADISON': '349.34', 'SIOUX CITY': '246.6', 'TOLEDO': '41.3', 'BANCROFT': '78.73'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/transportation_costs.csv', 'values': {'Unnamed: 0': 'PELLA', 'CLARINDA': '1181.6', 'FORT MADISON': '1458.53', 'SIOUX CITY': '1646.36', 'TOLEDO': '1924.55', 'BANCROFT': '38.93'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP6/transportation_costs.csv', 'values': {'Unnamed: 0': 'DES MOINES', 'CLARINDA': '1030.8', 'FORT MADISON': '43.48', 'SIOUX CITY': '932.4299999999999', 'TOLEDO': '55.39', 'BANCROFT': '103.84'}}]
import gurobipy as gp
from gurobipy import GRB
fixed_cost_records = [r for r in LEGACY_RECORDS if r['source'].endswith('fixed_cost.csv')]
suppliers = []
fixed_cost = {}
for rec in fixed_cost_records:
    name = rec['values']['Unnamed: 0']
    suppliers.append(name)
    fixed_cost[name] = float(rec['values']['fixed_costs'])
demand_records = [r for r in LEGACY_RECORDS if r['source'].endswith('demand.csv')]
store_names = ['CLARINDA', 'FORT MADISON', 'SIOUX CITY', 'TOLEDO', 'BANCROFT']
demands = {}
stores = []
for idx, rec in enumerate(demand_records):
    store = store_names[idx]
    stores.append(store)
    demands[store] = float(rec['values']['demand'])
transport_records = [r for r in LEGACY_RECORDS if r['source'].endswith('transportation_costs.csv')]
transport_cost = {}
for rec in transport_records:
    supplier = rec['values']['Unnamed: 0']
    transport_cost[supplier] = {}
    for store in store_names:
        transport_cost[supplier][store] = float(rec['values'][store])
M = sum((demands[store] for store in stores))
for i in suppliers:
    if i not in fixed_cost:
        raise ValueError(f'Missing fixed cost for supplier {i}')
    if i not in transport_cost:
        raise ValueError(f'Missing transport cost row for supplier {i}')
    for j in stores:
        if j not in transport_cost[i]:
            raise ValueError(f'Missing transport cost for supplier {i}, store {j}')
for j in stores:
    if j not in demands:
        raise ValueError(f'Missing demand for store {j}')
m = gp.Model('UFLP_Iowa_Liquor')
y_vars = m.addVars(suppliers, vtype=GRB.BINARY, name='')
x_vars = m.addVars(suppliers, stores, vtype=GRB.CONTINUOUS, lb=0, name='')
m.setObjective(gp.quicksum((fixed_cost[i] * y_vars[i] for i in suppliers)) + gp.quicksum((transport_cost[i][j] * x_vars[i, j] for i in suppliers for j in stores)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for i in suppliers)) == demands[j] for j in stores), name='')
m.addConstrs((gp.quicksum((x_vars[i, j] for j in stores)) <= M * y_vars[i] for i in suppliers), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')